import{_ as i,c as t,o,ae as a}from"./chunks/framework.Bw0Gm4PQ.js";const m=JSON.parse('{"title":"REGULATORY RELIEF TO PROMOTE DOMESTIC PRODUCTION OF","description":"","frontmatter":{"title":"REGULATORY RELIEF TO PROMOTE DOMESTIC PRODUCTION OF","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/05/regulatory-relief-to-promote-domestic-production-of-critical-medicines/","publishDate":"2025-05-05T18:09:40-04:00"},"headers":[],"relativePath":"executive-orders/2025-05-05-regulatory-relief-to-promote-domestic-production-of.md","filePath":"executive-orders/2025-05-05-regulatory-relief-to-promote-domestic-production-of.md"}'),r={name:"executive-orders/2025-05-05-regulatory-relief-to-promote-domestic-production-of.md"};function n(l,e,c,s,p,d){return o(),t("div",null,e[0]||(e[0]=[a('<h1 id="regulatory-relief-to-promote-domestic-production-of" tabindex="-1">REGULATORY RELIEF TO PROMOTE DOMESTIC PRODUCTION OF <a class="header-anchor" href="#regulatory-relief-to-promote-domestic-production-of" aria-label="Permalink to &quot;REGULATORY RELIEF TO PROMOTE DOMESTIC PRODUCTION OF&quot;">​</a></h1><p>Published: Monday, May 5, 2025</p><ul><li><p>The Executive Order aims to enhance domestic pharmaceutical production in the U.S. to improve health security and remedy prior inadequacies.</p></li><li><p>The previous administration made insufficient progress in establishing a resilient pharmaceutical supply chain, leading to critical information gaps.</p></li><li><p>Key issues affecting pharmaceutical manufacturing include:</p><ul><li>Lengthy construction timelines (5 to 10 years).</li><li>Complex federal, state, and local regulatory requirements.</li><li>Frequent FDA inspections of domestic manufacturers compared to international counterparts.</li></ul></li><li><p>The Administration intends to eliminate regulatory barriers to enhance domestic production capabilities and make the U.S. a competitive manufacturing hub.</p></li><li><p>The Secretary of Health and Human Services is tasked to:</p><ul><li>Review existing regulations and guidance for domestic pharmaceutical manufacturing within 180 days.</li><li>Streamline and accelerate regulatory processes, ensuring efficiency in inspections and approvals, especially for new technologies and production facilities.</li></ul></li><li><p>Specific responsibilities of the FDA Commissioner include:</p><ul><li>Evaluating and improving the current risk-based inspection approach, ensuring compliance with the Federal Food, Drug, and Cosmetic Act.</li><li>Enhancing programs to provide early technical advice to potential manufacturing facilities.</li><li>Improving enforcement of data reporting related to compliance.</li><li>Providing clearer guidance on site changes and component validations associated with domestic production.</li></ul></li><li><p>Within 90 days, the FDA Commissioner will:</p><ul><li>Develop improvements to the inspection regime for foreign manufacturing facilities, with funding from increased fees.</li><li>Publicly disclose detailed inspection data for foreign facilities.</li></ul></li><li><p>The Administrator of the EPA will update regulations pertaining to pharmaceutical manufacturing inspections within 180 days to enhance efficiency and reduce redundancy.</p></li><li><p>The Secretary of the Army will evaluate nationwide permits related to waterway regulations to support efficient pharmaceutical facility permitting within 180 days.</p></li><li><p>General provisions include:</p><ul><li>The Order does not alter the authority of existing agencies.</li><li>Implementation is subject to applicable laws and funding availability.</li><li>The Order does not confer enforceable rights against the U.S. or its entities.</li></ul></li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/05/regulatory-relief-to-promote-domestic-production-of-critical-medicines/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/05/regulatory-relief-to-promote-domestic-production-of-critical-medicines/</a></p>',4)]))}const f=i(r,[["render",n]]);export{m as __pageData,f as default};
